func Run(policy *security.Policy) Report {
	return RunWithMode(policy, ModeExpectedBehavior)
}

func RunStrictRustResult(policy *security.Policy) Report {
	return RunWithMode(policy, ModeStrictRustResult)
}

func RunWithMode(policy *security.Policy, mode Mode) Report {
	report := Report{Mode: mode, Total: len(Cases)}
	for _, tc := range Cases {
		got := security.CheckToolCall(tc.Tool, tc.Params, tc.Ctx, policy)
		if matches(tc, got, mode) {
			report.Passed++
			continue
		}
		report.Mismatches = append(report.Mismatches, Mismatch{
			Case:    tc,
			Got:     got,
			Message: mismatchMessage(tc, got, mode),
		})
	}
	return report
}

func matches(tc Case, got security.CheckResult, mode Mode) bool {
	if mode == ModeStrictRustResult {
		return got.Decision == tc.RustDecision && detailMatches(got, tc.RustDetail)
	}
	if tc.Behavior == BehaviorAllow {
		return got.Decision == security.DecisionAllow && detailMatches(got, "none")
	}
	if tc.RustDecision != security.DecisionAllow {
		return got.Decision == tc.RustDecision && detailMatches(got, tc.RustDetail)
	}
	return got.Decision != security.DecisionAllow
}

func mismatchMessage(tc Case, got security.CheckResult, mode Mode) string {
	if mode == ModeStrictRustResult {
		return fmt.Sprintf("want historical rust %s/%s got %s/%s source=%s rule=%s reason=%s", tc.RustDecision, tc.RustDetail, got.Decision, resultDetail(got), got.Source, got.RuleID, got.Reason)
	}
	if tc.Behavior == BehaviorAllow {
		return fmt.Sprintf("want allow/none got %s/%s source=%s rule=%s reason=%s", got.Decision, resultDetail(got), got.Source, got.RuleID, got.Reason)
	}
	if tc.RustDecision != security.DecisionAllow {
		return fmt.Sprintf("want detection matching rust %s/%s got %s/%s source=%s rule=%s reason=%s", tc.RustDecision, tc.RustDetail, got.Decision, resultDetail(got), got.Source, got.RuleID, got.Reason)
	}
	return fmt.Sprintf("want detection got allow/none; historical rust had %s/%s", tc.RustDecision, tc.RustDetail)
}

func detailMatches(got security.CheckResult, want string) bool {
	if want == "" {
		return true
	}
	if want == "none" {
		return got.Source == "none" && got.RuleID == ""
	}
	if strings.HasPrefix(want, "builtin.") || strings.HasPrefix(want, "powershell.") {
		return got.RuleID == want
	}
	return got.Source == want
}

func resultDetail(got security.CheckResult) string {
	if got.RuleID != "" {
		return got.RuleID
	}
	return got.Source
}
